WITH "__stat_src__" AS (SELECT *, "val" AS "__ggsql_aes_pos1__" FROM (SELECT * FROM ggsql_live_test) AS "__ggsql_src__"), "__bin_src__" AS (SELECT *, ((CASE WHEN (0) >= (CEILING(("__ggsql_aes_pos1__" - 1 + 1 * 0.5) / 1) - 1) THEN (0) ELSE (CEILING(("__ggsql_aes_pos1__" - 1 + 1 * 0.5) / 1) - 1) END)) * 1 + 1 - 1 * 0.5 AS "__ggsql_bin_key__" FROM "__stat_src__"), "__binned__" AS (SELECT "__ggsql_bin_key__" AS "__ggsql_stat_bin", COUNT(*) AS "__ggsql_stat_count" FROM "__bin_src__" GROUP BY "__ggsql_bin_key__") SELECT *, "__ggsql_stat_bin" AS "__ggsql_aes_pos1__", "__ggsql_stat_bin_end" AS "__ggsql_aes_pos1end__", "__ggsql_stat_count" AS "__ggsql_aes_pos2__" FROM (SELECT *, "__ggsql_stat_bin" + 1 AS "__ggsql_stat_bin_end", "__ggsql_stat_count" * 1.0 / SUM("__ggsql_stat_count") OVER () AS "__ggsql_stat_density" FROM "__binned__") AS "__ggsql_stat__";

-- case: boxplot_grouped
