SELECT TOP 1 * FROM (SELECT * FROM (SELECT * FROM ggsql_live_test) AS "__schema__") AS "__ggsql_lim__";
WITH "__ggsql_source__" AS (SELECT *, "grp" AS "__ggsql_aes_fill__", "val" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM ggsql_live_test) AS "__ggsql_src__") SELECT MIN("id") AS "__ggsql_min_id", MAX("id") AS "__ggsql_max_id", MIN("val") AS "__ggsql_min_val", MAX("val") AS "__ggsql_max_val", MIN("grp") AS "__ggsql_min_grp", MAX("grp") AS "__ggsql_max_grp", MIN("day") AS "__ggsql_min_day", MAX("day") AS "__ggsql_max_day", MIN("mixed Case") AS "__ggsql_min_mixed Case", MAX("mixed Case") AS "__ggsql_max_mixed Case", MIN("__ggsql_lim__") AS "__ggsql_min___ggsql_lim__", MAX("__ggsql_lim__") AS "__ggsql_max___ggsql_lim__" FROM "__ggsql_source__";
WITH bandwidth AS ( SELECT 0.9 * (CASE WHEN (SQRT(AVG("__ggsql_aes_pos1__"*"__ggsql_aes_pos1__") - AVG("__ggsql_aes_pos1__")*AVG("__ggsql_aes_pos1__"))) <= (((SELECT MAX(CASE WHEN rn = 1 + FLOOR(0.75 * (cnt - 1)) THEN __val END) + (MAX(CASE WHEN rn = 1 + CEILING(0.75 * (cnt - 1)) THEN __val END) - MAX(CASE WHEN rn = 1 + FLOOR(0.75 * (cnt - 1)) THEN __val END)) * MAX(0.75 * (cnt - 1) - FLOOR(0.75 * (cnt - 1))) FROM (SELECT "__ggsql_aes_pos1__" AS __val, ROW_NUMBER() OVER (PARTITION BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ORDER BY "__ggsql_aes_pos1__") AS rn, COUNT(*) OVER (PARTITION BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ) AS cnt, "__ggsql_aes_fill__", "__ggsql_aes_stroke__" FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "val" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM ggsql_live_test) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos1__" IS NOT NULL) AS "__ggsql_tile__" WHERE ("__ggsql_tile__"."__ggsql_aes_fill__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_fill__") AND ("__ggsql_tile__"."__ggsql_aes_stroke__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_stroke__")) - (SELECT MAX(CASE WHEN rn = 1 + FLOOR(0.25 * (cnt - 1)) THEN __val END) + (MAX(CASE WHEN rn = 1 + CEILING(0.25 * (cnt - 1)) THEN __val END) - MAX(CASE WHEN rn = 1 + FLOOR(0.25 * (cnt - 1)) THEN __val END)) * MAX(0.25 * (cnt - 1) - FLOOR(0.25 * (cnt - 1))) FROM (SELECT "__ggsql_aes_pos1__" AS __val, ROW_NUMBER() OVER (PARTITION BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ORDER BY "__ggsql_aes_pos1__") AS rn, COUNT(*) OVER (PARTITION BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ) AS cnt, "__ggsql_aes_fill__", "__ggsql_aes_stroke__" FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "val" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM ggsql_live_test) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos1__" IS NOT NULL) AS "__ggsql_tile__" WHERE ("__ggsql_tile__"."__ggsql_aes_fill__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_fill__") AND ("__ggsql_tile__"."__ggsql_aes_stroke__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_stroke__"))) / 1.34) THEN (SQRT(AVG("__ggsql_aes_pos1__"*"__ggsql_aes_pos1__") - AVG("__ggsql_aes_pos1__")*AVG("__ggsql_aes_pos1__"))) ELSE (((SELECT MAX(CASE WHEN rn = 1 + FLOOR(0.75 * (cnt - 1)) THEN __val END) + (MAX(CASE WHEN rn = 1 + CEILING(0.75 * (cnt - 1)) THEN __val END) - MAX(CASE WHEN rn = 1 + FLOOR(0.75 * (cnt - 1)) THEN __val END)) * MAX(0.75 * (cnt - 1) - FLOOR(0.75 * (cnt - 1))) FROM (SELECT "__ggsql_aes_pos1__" AS __val, ROW_NUMBER() OVER (PARTITION BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ORDER BY "__ggsql_aes_pos1__") AS rn, COUNT(*) OVER (PARTITION BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ) AS cnt, "__ggsql_aes_fill__", "__ggsql_aes_stroke__" FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "val" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM ggsql_live_test) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos1__" IS NOT NULL) AS "__ggsql_tile__" WHERE ("__ggsql_tile__"."__ggsql_aes_fill__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_fill__") AND ("__ggsql_tile__"."__ggsql_aes_stroke__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_stroke__")) - (SELECT MAX(CASE WHEN rn = 1 + FLOOR(0.25 * (cnt - 1)) THEN __val END) + (MAX(CASE WHEN rn = 1 + CEILING(0.25 * (cnt - 1)) THEN __val END) - MAX(CASE WHEN rn = 1 + FLOOR(0.25 * (cnt - 1)) THEN __val END)) * MAX(0.25 * (cnt - 1) - FLOOR(0.25 * (cnt - 1))) FROM (SELECT "__ggsql_aes_pos1__" AS __val, ROW_NUMBER() OVER (PARTITION BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ORDER BY "__ggsql_aes_pos1__") AS rn, COUNT(*) OVER (PARTITION BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ) AS cnt, "__ggsql_aes_fill__", "__ggsql_aes_stroke__" FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "val" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM ggsql_live_test) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos1__" IS NOT NULL) AS "__ggsql_tile__" WHERE ("__ggsql_tile__"."__ggsql_aes_fill__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_fill__") AND ("__ggsql_tile__"."__ggsql_aes_stroke__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_stroke__"))) / 1.34) END) * POWER(1.0 * COUNT(*), -0.2) AS bw, "__ggsql_aes_fill__", "__ggsql_aes_stroke__", MIN("__ggsql_aes_pos1__") AS x_min, MAX("__ggsql_aes_pos1__") AS x_max FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "val" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM ggsql_live_test) AS "__ggsql_src__") AS "__ggsql_qt__" WHERE "__ggsql_aes_pos1__" IS NOT NULL GROUP BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ), data AS ( SELECT "__ggsql_aes_fill__", "__ggsql_aes_stroke__", "__ggsql_aes_pos1__" AS val, 1.0 AS weight FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "val" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM ggsql_live_test) AS "__ggsql_src__") AS "__ggsql_data__" WHERE "__ggsql_aes_pos1__" IS NOT NULL ), "__ggsql_base__"(n) AS (SELECT 0 UNION ALL SELECT n + 1 FROM "__ggsql_base__" WHERE n < 7),"__ggsql_seq__"(n) AS (SELECT CAST(a.n * 64 + b.n * 8 + c.n AS REAL) AS n FROM "__ggsql_base__" a, "__ggsql_base__" b, "__ggsql_base__" c WHERE a.n * 64 + b.n * 8 + c.n < 512), global_range AS ( SELECT MIN(x_min) AS min, MAX(x_max) AS max, 3 * MAX(bw) AS expansion FROM bandwidth ), grid AS ( SELECT "__ggsql_aes_fill__", "__ggsql_aes_stroke__", ("__ggsql_global__".min - "__ggsql_global__".expansion) + (seq.n * (("__ggsql_global__".max - "__ggsql_global__".min) + 2 * "__ggsql_global__".expansion) / 511) AS x FROM global_range AS "__ggsql_global__" CROSS JOIN "__ggsql_seq__" AS seq CROSS JOIN (SELECT DISTINCT "__ggsql_aes_fill__", "__ggsql_aes_stroke__" FROM bandwidth) AS "__ggsql_groups__" ) SELECT *, "__ggsql_stat_pos1" AS "__ggsql_aes_pos1__", "__ggsql_stat_density" AS "__ggsql_aes_pos2__" FROM (SELECT "__ggsql_stat_pos1", "__ggsql_aes_fill__", "__ggsql_aes_stroke__", "__ggsql_stat_intensity", "__ggsql_stat_intensity" / "__norm" AS "__ggsql_stat_density" FROM ( SELECT grid.x AS "__ggsql_stat_pos1", grid."__ggsql_aes_fill__" AS "__ggsql_aes_fill__", grid."__ggsql_aes_stroke__" AS "__ggsql_aes_stroke__", SUM(data.weight * ((EXP(-0.5 * (grid.x - data.val) * (grid.x - data.val) / (bandwidth.bw * bandwidth.bw))) * 0.3989422804014327)) / MIN(bandwidth.bw) AS "__ggsql_stat_intensity", SUM(data.weight) AS "__norm" FROM data INNER JOIN bandwidth ON (data."__ggsql_aes_fill__" IS NOT DISTINCT FROM bandwidth."__ggsql_aes_fill__") AND (data."__ggsql_aes_stroke__" IS NOT DISTINCT FROM bandwidth."__ggsql_aes_stroke__") INNER JOIN grid ON (grid."__ggsql_aes_fill__" IS NOT DISTINCT FROM data."__ggsql_aes_fill__") AND (grid."__ggsql_aes_stroke__" IS NOT DISTINCT FROM data."__ggsql_aes_stroke__") GROUP BY grid.x, grid."__ggsql_aes_fill__", grid."__ggsql_aes_stroke__" ) AS "__ggsql_kde__") AS "__ggsql_stat__";

