SELECT TOP 1 * FROM (SELECT proj4text FROM spatial_ref_sys WHERE srid = 4326) AS "__ggsql_lim__";
SELECT ST_Transform(ST_SetSRID(ST_Point(0, 0), 4326), '+proj=merc +lon_0=0') AS g;

